def convert(input):
    # 获取历史步骤的输出数据，必须使用 get 方法
    id1_data = input.get('id1', {})

    # 获取历史步骤的输出数据中的字段值，优先使用 queryLoopWithTagValueListResult
    query_result = id1_data.get('queryLoopWithTagValueListResult', [])
    if query_result and isinstance(query_result, list) and len(query_result) > 0:
        loop_id = query_result[0].get('id', 0)
    else:
        loop_id = 0  # 默认值，确保类型为number

    # 确保类型为number
    if not isinstance(loop_id, (int, float)):
        loop_id = 0

    # 组装输出数据
    output = {
        'loopId': loop_id,
    }

    # 返回输出数据
    return output

